-- Dashboard initial schema (migration 001).
-- Source of truth for the database structure. The Go structs in
-- backend/internal/models/ mirror these tables for GORM.
--
-- Conventions:
--   * PKs are UUIDs generated by pgcrypto's gen_random_uuid().
--   * *_enc columns store CIPHERTEXT produced by the Go backend BEFORE insert
--     (application-side encryption). Postgres never sees plaintext and never
--     decrypts: no pgcrypto column encryption is used, only gen_random_uuid().
--   * Timestamps are timestamptz. updated_at is maintained by trigger.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- 1. Platform users.
CREATE TABLE users (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email                 VARCHAR(320) NOT NULL UNIQUE,
    password_hash         VARCHAR(255),              -- NULL for OAuth-only users
    is_confirmed          BOOLEAN NOT NULL DEFAULT FALSE,
    confirmation_token    VARCHAR(255) UNIQUE,       -- single-use, NULL once consumed
    confirmation_expires_at TIMESTAMPTZ,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 2. Persistent browser sessions.
-- The cookie value is an opaque UUID and is only useful while this row exists
-- and has not expired.
CREATE TABLE sessions (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_sessions_user_id ON sessions (user_id);
CREATE INDEX idx_sessions_expires_at ON sessions (expires_at);

-- 3. Static catalog of available services (weather, github, steam, rss...).
CREATE TABLE services (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name                VARCHAR(64) NOT NULL UNIQUE, -- technical identifier
    display_name        VARCHAR(128) NOT NULL,
    description         TEXT NOT NULL DEFAULT '',
    auth_type           VARCHAR(16) NOT NULL
        CHECK (auth_type IN ('none', 'api_key', 'credentials', 'oauth2')),
    oauth_client_id     VARCHAR(255),                -- app-level OAuth config,
    oauth_client_secret VARCHAR(255),                -- one row per service
    oauth_authorize_url TEXT,
    oauth_token_url     TEXT,
    oauth_scopes        TEXT
);

-- 3. User subscriptions to services.
CREATE TABLE user_services (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id                 UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    service_id              UUID NOT NULL REFERENCES services (id) ON DELETE CASCADE,
    external_username       VARCHAR(320),            -- 'credentials' services
    external_password_enc   TEXT,
    oauth_access_token_enc  TEXT,
    oauth_refresh_token_enc TEXT,
    oauth_token_expires_at  TIMESTAMPTZ,
    subscribed_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (user_id, service_id)
);
CREATE INDEX idx_user_services_user_id ON user_services (user_id);
CREATE INDEX idx_user_services_service_id ON user_services (service_id);

-- 4. Per-service widget catalog.
CREATE TABLE widgets (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    service_id   UUID NOT NULL REFERENCES services (id) ON DELETE CASCADE,
    name         VARCHAR(64) NOT NULL,               -- technical identifier
    display_name VARCHAR(128) NOT NULL,
    description  TEXT NOT NULL DEFAULT '',
    UNIQUE (service_id, name)
);
CREATE INDEX idx_widgets_service_id ON widgets (service_id);

-- 5. Configurable parameters of a catalog widget.
-- 'type' MUST stay in sync with the /about.json contract ("integer"|"string").
CREATE TABLE widget_params (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    widget_id     UUID NOT NULL REFERENCES widgets (id) ON DELETE CASCADE,
    name          VARCHAR(64) NOT NULL,
    type          VARCHAR(16) NOT NULL
        CHECK (type IN ('integer', 'string')),
    is_required   BOOLEAN NOT NULL DEFAULT FALSE,
    default_value TEXT,
    UNIQUE (widget_id, name)
);
CREATE INDEX idx_widget_params_widget_id ON widget_params (widget_id);

-- 6. Configured widget instances placed on a user's dashboard.
CREATE TABLE widget_instances (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id              UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    widget_id            UUID NOT NULL REFERENCES widgets (id) ON DELETE CASCADE,
    config               JSONB NOT NULL DEFAULT '{}', -- this instance's param values
    refresh_rate_seconds INTEGER NOT NULL CHECK (refresh_rate_seconds > 0),
    position_x           INTEGER NOT NULL DEFAULT 0,
    position_y           INTEGER NOT NULL DEFAULT 0,
    last_refreshed_at    TIMESTAMPTZ,                 -- read by the timer
    cached_data          JSONB,                       -- last fetch result
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_widget_instances_user_id ON widget_instances (user_id);
CREATE INDEX idx_widget_instances_widget_id ON widget_instances (widget_id);
CREATE INDEX idx_widget_instances_last_refreshed_at ON widget_instances (last_refreshed_at);

-- Keep updated_at fresh on UPDATE.
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_users_updated_at
    BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TRIGGER trg_widget_instances_updated_at
    BEFORE UPDATE ON widget_instances
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
